package main

import (
	"fmt"
	"strings"
	"unicode"
	"unicode/utf8"
)

type tokenType int

const (
	tokenEOF tokenType = iota
	tokenWord
	tokenSemi
	tokenPipe
	tokenAndIf
	tokenOrIf
	tokenRedirectIn
	tokenRedirectOut
	tokenRedirectAppend
	tokenBad
)

type partKind int

const (
	partLiteral partKind = iota
	partVariable
	partCommandSub
)

type wordPart struct {
	kind   partKind
	text   string
	quoted bool
}

type wordNode struct {
	parts         []wordPart
	tildeEligible bool
	globEligible  bool
}

type redirectNode struct {
	kind tokenType
	word wordNode
}

type commandNode struct {
	words     []wordNode
	redirects []redirectNode
}

type pipelineNode struct {
	commands []commandNode
}

type andOrRest struct {
	op       tokenType
	pipeline pipelineNode
}

type andOrNode struct {
	first pipelineNode
	rest  []andOrRest
}

type scriptNode struct {
	nodes []andOrNode
}

type token struct {
	typ  tokenType
	word wordNode
	text string
	line int
	col  int
}

type parseError struct {
	input   string
	line    int
	col     int
	message string
}

func (e *parseError) Error() string {
	lineText := sourceLine(e.input, e.line)
	return fmt.Sprintf("nsh: parse error:  --> %d:%d\n  |\n%d | %s\n  | %s^---\n  |\n  = %s\n",
		e.line, e.col, e.line, lineText, strings.Repeat(" ", max(0, e.col-1)), e.message)
}

type tokenizer struct {
	input string
	index int
	line  int
	col   int
}

func newTokenizer(input string) *tokenizer {
	return &tokenizer{
		input: input,
		line:  1,
		col:   1,
	}
}

func parseScript(input string) (*scriptNode, *parseError) {
	p := &parser{tz: newTokenizer(input), input: input}
	return p.parse()
}

func parseScriptSafe(input string) (node *scriptNode, err *parseError) {
	defer func() {
		if recovered := recover(); recovered != nil {
			if parseErr, ok := recovered.(*parseError); ok {
				node = nil
				err = parseErr
				return
			}
			panic(recovered)
		}
	}()
	return parseScript(input)
}

type parser struct {
	tz    *tokenizer
	input string
	peek  *token
}

func (p *parser) parse() (*scriptNode, *parseError) {
	node := &scriptNode{}
	p.skipSeparators()
	if tok := p.peekToken(); tok.typ == tokenEOF {
		return node, nil
	}

	for {
		andOr, err := p.parseAndOr()
		if err != nil {
			return nil, err
		}
		node.nodes = append(node.nodes, andOr)

		tok := p.peekToken()
		if tok.typ == tokenEOF {
			break
		}
		if tok.typ != tokenSemi {
			return nil, p.unexpected(tok, "expected command")
		}
		p.nextToken()
		p.skipSeparators()
		if p.peekToken().typ == tokenEOF {
			break
		}
	}
	return node, nil
}

func (p *parser) parseAndOr() (andOrNode, *parseError) {
	first, err := p.parsePipeline()
	if err != nil {
		return andOrNode{}, err
	}
	node := andOrNode{first: first}
	for {
		tok := p.peekToken()
		if tok.typ != tokenAndIf && tok.typ != tokenOrIf {
			return node, nil
		}
		p.nextToken()
		nextPipe, perr := p.parsePipeline()
		if perr != nil {
			return andOrNode{}, perr
		}
		node.rest = append(node.rest, andOrRest{
			op:       tok.typ,
			pipeline: nextPipe,
		})
	}
}

func (p *parser) parsePipeline() (pipelineNode, *parseError) {
	cmd, err := p.parseCommand()
	if err != nil {
		return pipelineNode{}, err
	}
	pipe := pipelineNode{commands: []commandNode{cmd}}
	for p.peekToken().typ == tokenPipe {
		p.nextToken()
		nextCmd, perr := p.parseCommand()
		if perr != nil {
			return pipelineNode{}, perr
		}
		pipe.commands = append(pipe.commands, nextCmd)
	}
	return pipe, nil
}

func (p *parser) parseCommand() (commandNode, *parseError) {
	cmd := commandNode{}
	sawItem := false
	for {
		tok := p.peekToken()
		switch tok.typ {
		case tokenWord:
			p.nextToken()
			sawItem = true
			if len(cmd.words) == 0 {
				if reserved, ok := literalWord(tok.word); ok && isReservedWord(reserved) {
					return commandNode{}, &parseError{
						input:   p.input,
						line:    tok.line,
						col:     tok.col + utf8.RuneCountInString(reserved),
						message: "expected command or compound_list_sep",
					}

package main

import (
	"os"
	"strconv"
	"strings"
	"syscall"
	"unsafe"
)

func isTTY(fd uintptr) bool {
	var termios syscall.Termios
	_, _, errno := syscall.Syscall6(
		syscall.SYS_IOCTL,
		fd,
		uintptr(syscall.TCGETS),
		uintptr(unsafe.Pointer(&termios)),
		0,
		0,
		0,
	)
	return errno == 0
}

func formatRustOsError(err error) string {
	if pathErr, ok := err.(*os.PathError); ok {
		if errno, ok := pathErr.Err.(syscall.Errno); ok {
			return formatRustErrno(errno)
		}
	}
	if errno, ok := err.(syscall.Errno); ok {
		return formatRustErrno(errno)
	}
	return err.Error()
}

func formatRustErrno(errno syscall.Errno) string {
	kind := "Other"
	switch errno {
	case syscall.ENOENT:
		kind = "NotFound"
	case syscall.EACCES, syscall.EPERM:
		kind = "PermissionDenied"
	case syscall.EEXIST:
		kind = "AlreadyExists"
	}
	return "Os { code: " + strconv.Itoa(int(errno)) + ", kind: " + kind + ", message: " + quote(errno.Error()) + " }"
}

func quote(value string) string {
	return `"` + strings.ReplaceAll(value, `"`, `\"`) + `"`
}

package main

import (
	"bufio"
	"bytes"
	"fmt"
	"io"
	"os"
	"os/exec"
	"os/user"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"sync"
)

const defaultPrompt = `\{cyan}\{bold}\{current_dir} \$\{reset} `

type shell struct {
	stdin  io.Reader
	stdout io.Writer
	stderr io.Writer

	env        map[string]string
	aliases    map[string]string
	aliasOrder []string

	cwd    string
	home   string
	oldpwd string
	prompt string
	login  bool

	lastStatus int
}

type assignment struct {
	name  string
	value string
}

func newShell(stdin io.Reader, stdout, stderr io.Writer) (*shell, error) {
	cwd, err := os.Getwd()
	if err != nil {
		return nil, err
	}

	env := map[string]string{}
	for _, entry := range os.Environ() {
		name, value, ok := strings.Cut(entry, "=")
		if ok {
			env[name] = value
		}
	}

	home := env["HOME"]
	if home == "" {
		if value, err := os.UserHomeDir(); err == nil {
			home = value
			env["HOME"] = value
		}
	}

	prompt := env["PROMPT"]
	if prompt == "" {
		prompt = defaultPrompt
	}

	return &shell{
		stdin:      stdin,
		stdout:     stdout,
		stderr:     stderr,
		env:        env,
		aliases:    map[string]string{},
		cwd:        cwd,
		home:       home,
		prompt:     prompt,
		lastStatus: 0,
	}, nil
}

func (s *shell) clone(stdout io.Writer) *shell {
	env := make(map[string]string, len(s.env))
	for key, value := range s.env {
		env[key] = value
	}
	aliases := make(map[string]string, len(s.aliases))
	for key, value := range s.aliases {
		aliases[key] = value
	}
	order := append([]string(nil), s.aliasOrder...)
	return &shell{
		stdin:      s.stdin,
		stdout:     stdout,
		stderr:     s.stderr,
		env:        env,
		aliases:    aliases,
		aliasOrder: order,
		cwd:        s.cwd,
		home:       s.home,
		oldpwd:     s.oldpwd,
		prompt:     s.prompt,
		login:      s.login,
		lastStatus: s.lastStatus,
	}
}

func (s *shell) ensureStateFiles() {
	if s.home == "" {
		return
	}
	logPath := filepath.Join(s.home, ".nsh.log")
	if _, err := os.OpenFile(logPath, os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0o644); err != nil {
		panicOpenHomeFile("~/.nsh.log", err)
	}
	historyPath := filepath.Join(s.home, ".nsh_history")
	if _, err := os.OpenFile(historyPath, os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0o644); err != nil {
		panicOpenHomeFile("~/.nsh_history", err)
	}
}

func (s *shell) loadRCFiles() int {
	var paths []string
	if s.home != "" {
		paths = append(paths, filepath.Join(s.home, ".nshrc"))
	}
	if xdg := s.env["XDG_CONFIG_HOME"]; xdg != "" {
		paths = append(paths, filepath.Join(xdg, "nsh", "nshrc"))
	}

	for _, path := range paths {
		content, err := os.ReadFile(path)
		if err != nil {
			if os.IsNotExist(err) {
				continue
			}
			return 1
		}
		status, exited := s.executeStringWithIO(string(content), s.stdin, s.stdout, s.stderr)
		if exited {
			return status
		}
	}
	return 0
}

func (s *shell) executeString(script string) int {
	status, _ := s.executeStringWithIO(script, s.stdin, s.stdout, s.stderr)
	return status
}

func (s *shell) executeStringWithIO(script string, stdin io.Reader, stdout, stderr io.Writer) (status int, exited bool) {
	node, err := parseScriptSafe(script)
	if err != nil {
		fmt.Fprint(stderr, err.Error())
		s.lastStatus = 255
		return 255, false
	}
	return s.executeNode(node, stdin, stdout, stderr)
}

func (s *shell) executeNode(node *scriptNode, stdin io.Reader, stdout, stderr io.Writer) (status int, exited bool) {
	status = 0
	for _, andOr := range node.nodes {
		nextStatus, nextExited := s.runAndOr(andOr, stdin, stdout, stderr)
		status = nextStatus
		s.lastStatus = status
		if nextExited {
			return status, true
		}
	}
	return status, false
}

func (s *shell) repl() int {
	reader := bufio.NewReader(s.stdin)
	for {
		fmt.Fprint(s.stdout, s.renderPrompt())
		line, err := reader.ReadString('\n')
		if err == io.EOF {
			if line == "" {
				return 0
			}
		} else if err != nil {
			return 1
		}

		status, exited := s.executeStringWithIO(line, s.stdin, s.stdout, s.stderr)
		s.lastStatus = status
		if exited {
			return status
		}
		if err == io.EOF {
			return status
		}
	}
}

func (s *shell) runAndOr(node andOrNode, stdin io.Reader, stdout, stderr io.Writer) (int, bool) {
	status, exited := s.runPipeline(node.first, stdin, stdout, stderr)
	if exited {
		return status, true
	}

	for _, rest := range node.rest {
		if rest.op == tokenAndIf && status != 0 {
			continue
		}
		if rest.op == tokenOrIf && status == 0 {
			continue
		}
		status, exited = s.runPipeline(rest.pipeline, stdin, stdout, stderr)
		if exited {
			return status, true
		}
	}
	return status, false
}

func (s *shell) runPipeline(node pipelineNode, stdin io.Reader, stdout, stderr io.Writer) (int, bool) {
	if len(node.commands) == 1 {
		return s.runCommand(node.commands[0], stdin, stdout, stderr)
	}

	type result struct {
		index  int
		status int
		exited bool
	}

	results := make(chan result, len(node.commands))
	var wg sync.WaitGroup
	input := stdin

	for i, cmdNode := range node.commands {
		stageShell := s.clone(stdout)
		stageIn := input
		stageOut := stdout
		var pipeReader *io.PipeReader
		var pipeWriter *io.PipeWriter
		if i < len(node.commands)-1 {
			pipeReader, pipeWriter = io.Pipe()
			stageOut = pipeWriter
		}

		wg.Add(1)
		go func(index int, cmdNode commandNode, sh *shell, in io.Reader, out io.Writer, closer *io.PipeWriter) {
			defer wg.Done()
			status, exited := sh.runCommand(cmdNode, in, out, stderr)
			if closer != nil {
				closer.Close()
			}
			results <- result{index: index, status: status, exited: exited}
		}(i, cmdNode, stageShell, stageIn, stageOut, pipeWriter)

		if pipeReader != nil {
			input = pipeReader
		}
	}

func (s *shell) runPipeline(node pipelineNode, stdin io.Reader, stdout, stderr io.Writer) (int, bool) {
	if len(node.commands) == 1 {
		return s.runCommand(node.commands[0], stdin, stdout, stderr)
	}

	type result struct {
		index  int
		status int
		exited bool
	}

	results := make(chan result, len(node.commands))
	var wg sync.WaitGroup
	input := stdin

	for i, cmdNode := range node.commands {
		stageShell := s.clone(stdout)
		stageIn := input
		stageOut := stdout
		var pipeReader *io.PipeReader
		var pipeWriter *io.PipeWriter
		if i < len(node.commands)-1 {
			pipeReader, pipeWriter = io.Pipe()
			stageOut = pipeWriter
		}

		wg.Add(1)
		go func(index int, cmdNode commandNode, sh *shell, in io.Reader, out io.Writer, closer *io.PipeWriter) {
			defer wg.Done()
			status, exited := sh.runCommand(cmdNode, in, out, stderr)
			if closer != nil {
				closer.Close()
			}
			results <- result{index: index, status: status, exited: exited}
		}(i, cmdNode, stageShell, stageIn, stageOut, pipeWriter)

		if pipeReader != nil {
			input = pipeReader
		}
	}

	wg.Wait()
	close(results)

	lastStatus := 0
	lastExited := false
	for result := range results {
		if result.index == len(node.commands)-1 {
			lastStatus = result.status
			lastExited = result.exited
		}
	}
	return lastStatus, lastExited
}

func (s *shell) runCommand(node commandNode, stdin io.Reader, stdout, stderr io.Writer) (int, bool) {
	assignments, words := splitAssignments(node.words)
	words = s.expandAliases(words)

	localIn := stdin
	localOut := stdout
	closers := []io.Closer{}
	defer func() {
		for _, closer := range closers {
			closer.Close()
		}
	}()

	commandEnv := make(map[string]string, len(s.env))
	for key, value := range s.env {
		commandEnv[key] = value
	}
	for _, assignment := range assignments {
		commandEnv[assignment.name] = assignment.value
	}

	for _, redirect := range node.redirects {
		targets := s.expandWordToArgs(redirect.word)
		target := ""
		if len(targets) > 0 {
			target = targets[0]
		}
		if target == "" {
			target = "."
		}
		switch redirect.kind {
		case tokenRedirectIn:
			file, err := os.Open(s.resolvePath(target))
			if err != nil {
				fmt.Fprintf(stderr, "nsh: %v\n", err)
				return 1, false
			}
			closers = append(closers, file)
			localIn = file
		case tokenRedirectOut:
			file, err := os.OpenFile(s.resolvePath(target), os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0o644)
			if err != nil {
				fmt.Fprintf(stderr, "nsh: %v\n", err)
				return 1, false
			}
			closers = append(closers, file)
			localOut = file
		case tokenRedirectAppend:
			file, err := os.OpenFile(s.resolvePath(target), os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0o644)
			if err != nil {
				fmt.Fprintf(stderr, "nsh: %v\n", err)
				return 1, false
			}
			closers = append(closers, file)
			localOut = file
		}
	}

	if len(words) == 0 {
		for _, assignment := range assignments {
			s.setEnv(assignment.name, assignment.value)
		}
		return 0, false
	}

	args := s.expandWords(words)
	if len(args) == 0 {
		return 0, false
	}

	switch args[0] {
	case "exit":
		for _, assignment := range assignments {
			s.setEnv(assignment.name, assignment.value)
		}
		return s.runExit(args[1:]), true
	case "cd":
		for _, assignment := range assignments {
			s.setEnv(assignment.name, assignment.value)
		}
		return s.runCD(args[1:], stderr), false
	case "alias":
		for _, assignment := range assignments {
			s.setEnv(assignment.name, assignment.value)
		}
		return s.runAlias(args[1:], localOut), false
	case "export":
		for _, assignment := range assignments {
			s.setEnv(assignment.name, assignment.value)
		}
		return s.runExport(args[1:]), false
	case "pwd":
		for _, assignment := range assignments {
			s.setEnv(assignment.name, assignment.value)
		}
		fmt.Fprintln(localOut, s.cwd)
		return 0, false
	}

	return s.runExternal(args, commandEnv, localIn, localOut, stderr), false
}

func (s *shell) runExit(args []string) int {
	if len(args) == 0 {
		return s.lastStatus
	}
	status, err := strconv.Atoi(args[0])
	if err != nil {
		return 1
	}
	return status
}

func (s *shell) runCD(args []string, stderr io.Writer) int {
	target := s.home
	if len(args) > 0 {
		target = args[0]
	}
	if target == "" {
		return 1
	}
	if target == "-" {
		if s.oldpwd == "" {
			return 1
		}
		target = s.oldpwd
	}
	target = s.expandTilde(target)
	resolved := s.resolvePath(target)
	oldpwd := s.cwd
	if err := os.Chdir(resolved); err != nil {
		if os.IsNotExist(err) {
			fmt.Fprintf(stderr, "nsh: cd: No such file or directory (os error 2): `%s'\n", target)
		} else {
			fmt.Fprintf(stderr, "nsh: cd: %v: `%s'\n", err, target)
		}
		return 1
	}
	s.oldpwd = oldpwd
	s.cwd = resolved
	return 0
}

func (s *shell) runAlias(args []string, stdout io.Writer) int {
	if len(args) == 0 {
		for _, name := range s.aliasOrder {
			fmt.Fprintf(stdout, "%s='%s'\n", name, s.aliases[name])
		}
		return 0
	}
	for _, arg := range args {
		name, value, ok := strings.Cut(arg, "=")
		if !ok || name == "" {
			if alias, exists := s.aliases[arg]; exists {
				fmt.Fprintf(stdout, "%s='%s'\n", arg, alias)
			}
			continue
		}
		s.setAlias(name, value)
	}
	return 0
}

func (s *shell) runExport(args []string) int {
	for _, arg := range args {
		if name, value, ok := strings.Cut(arg, "="); ok {
			s.setEnv(name, value)
			continue
		}
		if _, exists := s.env[arg]; !exists {
			s.env[arg] = ""
		}
	}
	return 0
}

func (s *shell) runExternal(args []string, env map[string]string, stdin io.Reader, stdout, stderr io.Writer) int {
	path, err := lookupExecutable(args[0], env["PATH"], s.cwd)
	if err != nil {
		fmt.Fprintf(stderr, "nsh: command not found `%s'\n", args[0])
		return 1
	}
	cmd := exec.Command(path, args[1:]...)
	cmd.Dir = s.cwd
	cmd.Env = envList(env)
	cmd.Stdin = stdin
	cmd.Stdout = stdout
	cmd.Stderr = stderr
	if err := cmd.Run(); err != nil {
		if exitErr, ok := err.(*exec.ExitError); ok {
			return exitErr.ExitCode()
		}
		return 1
	}
	return 0
}

func (s *shell) expandAliases(words []wordNode) []wordNode {
	if len(words) == 0 {
		return words
	}
	assignments, rest := splitAssignments(words)
	if len(rest) == 0 {
		return words
	}
	current := append([]wordNode(nil), rest...)
	for i := 0; i < 16; i++ {
		name, ok := literalWord(current[0])
		if !ok {
			break
		}
		aliasText, exists := s.aliases[name]
		if !exists {
			break
		}
		replacement, ok := parseAliasWords(aliasText)
		if !ok || len(replacement) == 0 {
			break
		}
		current = append(append([]wordNode(nil), replacement...), current[1:]...)
	}
	result := make([]wordNode, 0, len(assignments)+len(current))
	for _, assignment := range assignments {
		result = append(result, assignmentWord(assignment))
	}
	result = append(result, current...)
	return result
}

func (s *shell) expandWords(words []wordNode) []string {
	var args []string
	for _, word := range words {
		args = append(args, s.expandWordToArgs(word)...)
	}
	return args
}

func (s *shell) expandWordToArgs(word wordNode) []string {
	value := s.expandWord(word)
	if word.globEligible {
		if matches := s.expandGlob(value); len(matches) > 0 {
			return matches
		}
	}
	return []string{value}

