			cmd.words = append(cmd.words, tok.word)
		case tokenRedirectIn, tokenRedirectOut, tokenRedirectAppend:
			redirTok := p.nextToken()
			target := p.nextToken()
			if target.typ != tokenWord {
				return commandNode{}, p.unexpected(target, "expected redirect target")
			}
			sawItem = true
			cmd.redirects = append(cmd.redirects, redirectNode{
				kind: redirTok.typ,
				word: target.word,
			})
		case tokenBad:
			return commandNode{}, p.unexpected(tok, "expected command")
		default:
			if !sawItem {
				return commandNode{}, p.unexpected(tok, "expected command")
			}
			return cmd, nil
		}
	}
}

func (p *parser) skipSeparators() {
	for p.peekToken().typ == tokenSemi {
		p.nextToken()
	}
}

func (p *parser) peekToken() token {
	if p.peek == nil {
		tok := p.tz.next()
		p.peek = &tok
	}
	return *p.peek
}

func (p *parser) nextToken() token {
	tok := p.peekToken()
	p.peek = nil
	return tok
}

func (p *parser) unexpected(tok token, message string) *parseError {
	line := tok.line
	col := tok.col
	if tok.typ == tokenEOF {
		line = p.tz.line
		col = p.tz.col
	}
	return &parseError{
		input:   p.input,
		line:    line,
		col:     col,
		message: message,
	}
}

func (t *tokenizer) next() token {
	for {
		if t.eof() {
			return token{typ: tokenEOF, line: t.line, col: t.col}
		}
		ch := t.peek()
		switch ch {
		case ' ', '\t', '\r':
			t.advance()
		case '\n':
			line, col := t.line, t.col
			t.advance()
			return token{typ: tokenSemi, line: line, col: col}
		case '#':
			t.skipComment()
		case ';':
			line, col := t.line, t.col
			t.advance()
			return token{typ: tokenSemi, line: line, col: col}
		case '&':
			line, col := t.line, t.col
			t.advance()
			if !t.eof() && t.peek() == '&' {
				t.advance()
				return token{typ: tokenAndIf, line: line, col: col}
			}
			return token{typ: tokenBad, text: "&", line: line, col: col}
		case '|':
			line, col := t.line, t.col
			t.advance()
			if !t.eof() && t.peek() == '|' {
				t.advance()
				return token{typ: tokenOrIf, line: line, col: col}
			}
			return token{typ: tokenPipe, line: line, col: col}
		case '>':
			line, col := t.line, t.col
			t.advance()
			if !t.eof() && t.peek() == '>' {
				t.advance()
				return token{typ: tokenRedirectAppend, line: line, col: col}
			}
			return token{typ: tokenRedirectOut, line: line, col: col}
		case '<':
			line, col := t.line, t.col
			t.advance()
			return token{typ: tokenRedirectIn, line: line, col: col}
		case '(', ')':
			line, col := t.line, t.col
			text := string(ch)
			t.advance()
			return token{typ: tokenBad, text: text, line: line, col: col}
		default:
			return t.word()
		}
	}
}

func (t *tokenizer) word() token {
	line, col := t.line, t.col
	word := wordNode{
		tildeEligible: t.peek() == '~',
	}
	var literal strings.Builder
	literalQuoted := false

	flushLiteral := func() {
		if literal.Len() == 0 {
			return
		}
		word.parts = append(word.parts, wordPart{
			kind:   partLiteral,
			text:   literal.String(),
			quoted: literalQuoted,
		})
		literal.Reset()
	}

	appendLiteral := func(text string, quoted bool) {
		if literal.Len() > 0 && literalQuoted != quoted {
			flushLiteral()
		}
		literalQuoted = quoted
		literal.WriteString(text)
		if !quoted && strings.ContainsAny(text, "*?[") {
			word.globEligible = true
		}
	}

	for !t.eof() {
		ch := t.peek()
		if isWordBoundary(ch) {
			break
		}
		switch ch {
		case '\'':
			flushLiteral()
			t.advance()
			start := t.index
			for !t.eof() && t.peek() != '\'' {
				t.advance()
			}
			if t.eof() {
				panic(t.parseErr("expected closing single quote"))
			}
			appendLiteral(t.input[start:t.index], true)
			t.advance()
		case '"':
			flushLiteral()
			t.advance()
			for {
				if t.eof() {
					panic(t.parseErr("expected closing double quote"))
				}
				ch = t.peek()
				if ch == '"' {
					t.advance()
					break
				}
				if ch == '\\' {
					t.advance()
					if t.eof() {
						break
					}
					next := t.peek()
					switch next {
					case '$', '"', '\\':
						appendLiteral(string(next), true)
						t.advance()
					case '\n':
						t.advance()
					default:
						appendLiteral("\\"+string(next), true)
						t.advance()
					}
					continue
				}
				if ch == '$' {
					t.advance()
					if part, ok := t.variablePart(true); ok {
						flushLiteral()
						word.parts = append(word.parts, part)
						continue
					}
					appendLiteral("$", true)
					continue
				}
				appendLiteral(string(ch), true)
				t.advance()
			}
		case '\\':
			t.advance()
			if t.eof() {
				appendLiteral("\\", false)
				break
			}
			if t.peek() == '\n' {
				t.advance()
				continue
			}
			appendLiteral(string(t.peek()), false)
			t.advance()
		case '$':
			t.advance()
			if part, ok := t.variablePart(false); ok {
				flushLiteral()
				word.parts = append(word.parts, part)
			} else {
				appendLiteral("$", false)
			}
		default:
			appendLiteral(string(ch), false)
			t.advance()
		}
	}

	flushLiteral()
	return token{
		typ:  tokenWord,
		word: word,
		line: line,
		col:  col,
	}
}

func (t *tokenizer) variablePart(quoted bool) (wordPart, bool) {
	if t.eof() {
		return wordPart{}, false
	}
	switch t.peek() {
	case '(':
		t.advance()
		startLine, startCol := t.line, t.col
		script, err := t.readCommandSub()
		if err != nil {
			panic(&parseError{
				input:   t.input,
				line:    startLine,
				col:     startCol,
				message: err.Error(),
			})
		}
		return wordPart{kind: partCommandSub, text: script, quoted: quoted}, true
	case '{':
		t.advance()
		start := t.index
		for !t.eof() && t.peek() != '}' {
			t.advance()
		}
		if t.eof() {
			panic(t.parseErr("expected closing }"))
		}
		name := t.input[start:t.index]
		t.advance()
		return wordPart{kind: partVariable, text: name, quoted: quoted}, true
	case '#', '?':
		ch := t.peek()
		t.advance()
		return wordPart{kind: partVariable, text: string(ch), quoted: quoted}, true
	}

	if unicode.IsDigit(rune(t.peek())) {
		ch := t.peek()
		t.advance()
		return wordPart{kind: partVariable, text: string(ch), quoted: quoted}, true
	}

	if !isVarStart(t.peek()) {
		return wordPart{}, false
	}
	start := t.index
	t.advance()
	for !t.eof() && isVarContinue(t.peek()) {
		t.advance()
	}
	return wordPart{kind: partVariable, text: t.input[start:t.index], quoted: quoted}, true
}

func (t *tokenizer) readCommandSub() (string, error) {
	start := t.index

	start := t.index
	depth := 1
	for !t.eof() {
		ch := t.peek()
		switch ch {
		case '\'':
			t.advance()
			for !t.eof() && t.peek() != '\'' {
				t.advance()
			}
			if t.eof() {
				return "", fmt.Errorf("expected closing single quote")
			}
			t.advance()
		case '"':
			t.advance()
			for !t.eof() {
				ch = t.peek()
				if ch == '"' {
					t.advance()
					break
				}
				if ch == '\\' {
					t.advance()
					if !t.eof() {
						t.advance()
					}
					continue
				}
				if ch == '$' {
					t.advance()
					if !t.eof() && t.peek() == '(' {
						t.advance()
						depth++
						continue
					}
					continue
				}
				t.advance()
			}
			if t.eof() {
				return "", fmt.Errorf("expected closing double quote")
			}
		case '\\':
			t.advance()
			if !t.eof() {
				t.advance()
			}
		case '$':
			t.advance()
			if !t.eof() && t.peek() == '(' {
				t.advance()
				depth++
			}
		case ')':
			t.advance()
			depth--
			if depth == 0 {
				return t.input[start : t.index-1], nil
			}
		default:
			t.advance()
		}
	}
	return "", fmt.Errorf("expected closing )")
}

func (t *tokenizer) skipComment() {
	for !t.eof() && t.peek() != '\n' {
		t.advance()
	}
}

func (t *tokenizer) parseErr(message string) *parseError {
	return &parseError{
		input:   t.input,
		line:    t.line,
		col:     t.col,
		message: message,
	}
}

func (t *tokenizer) eof() bool {
	return t.index >= len(t.input)
}

func (t *tokenizer) peek() byte {
	return t.input[t.index]
}

func (t *tokenizer) advance() {
	if t.eof() {
		return
	}
	_, size := utf8.DecodeRuneInString(t.input[t.index:])
	if size == 0 {
		size = 1
	}
	if t.input[t.index] == '\n' {
		t.line++
		t.col = 1
	} else {
		t.col++
	}
	t.index += size
}

func sourceLine(input string, line int) string {
	lines := strings.Split(input, "\n")
	if line <= 0 || line > len(lines) {
		return ""
	}
	return lines[line-1]
}

func isWordBoundary(ch byte) bool {
	switch ch {
	case ' ', '\t', '\r', '\n', ';', '|', '&', '>', '<':
		return true
	}
	return false
}

func isVarStart(ch byte) bool {
	return ch == '_' || unicode.IsLetter(rune(ch))
}

func isVarContinue(ch byte) bool {
	return ch == '_' || unicode.IsLetter(rune(ch)) || unicode.IsDigit(rune(ch))
}

func literalWord(word wordNode) (string, bool) {
	if len(word.parts) == 0 {
		return "", false
	}
	var b strings.Builder
	for _, part := range word.parts {
		if part.kind != partLiteral {
			return "", false
		}
		b.WriteString(part.text)
	}
	return b.String(), true
}

func isReservedWord(word string) bool {
	switch word {
	case "if", "then", "elif", "else", "fi", "for", "while", "until", "do", "done", "case", "esac", "{", "}":
		return true
	default:
		return false
	}
}

func max(a, b int) int {
	if a > b {
		return a
	}
	return b
}

	return []string{value}
}

func (s *shell) expandWord(word wordNode) string {
	var b strings.Builder
	for _, part := range word.parts {
		switch part.kind {
		case partLiteral:
			b.WriteString(part.text)
		case partVariable:
			b.WriteString(s.expandVariable(part.text))
		case partCommandSub:
			b.WriteString(s.expandCommandSub(part.text))
		}
	}
	value := b.String()
	if word.tildeEligible {
		value = s.expandTilde(value)
	}
	return value
}

func (s *shell) expandVariable(name string) string {
	switch name {
	case "#":
		return "0"
	case "?":
		return strconv.Itoa(s.lastStatus)
	}
	if len(name) == 1 && name[0] >= '0' && name[0] <= '9' {
		return ""
	}
	return s.env[name]
}

func (s *shell) expandCommandSub(script string) string {
	var out bytes.Buffer
	clone := s.clone(&out)
	clone.stdin = bytes.NewReader(nil)
	clone.executeStringWithIO(script, clone.stdin, &out, s.stderr)
	return strings.TrimRight(out.String(), "\n")
}

func (s *shell) expandTilde(value string) string {
	if value == "~" {
		return s.home
	}
	if strings.HasPrefix(value, "~/") {
		return filepath.Join(s.home, value[2:])
	}
	return value
}

func (s *shell) expandGlob(pattern string) []string {
	if !strings.ContainsAny(pattern, "*?[") {
		return nil
	}
	if filepath.IsAbs(pattern) {
		matches, _ := filepath.Glob(pattern)
		return matches
	}
	matches, _ := filepath.Glob(filepath.Join(s.cwd, pattern))
	if len(matches) == 0 {
		return nil
	}
	rel := make([]string, 0, len(matches))
	for _, match := range matches {
		value, err := filepath.Rel(s.cwd, match)
		if err != nil {
			rel = append(rel, match)
			continue
		}
		rel = append(rel, value)
	}
	sort.Strings(rel)
	return rel
}

func (s *shell) resolvePath(path string) string {
	if filepath.IsAbs(path) {
		return path
	}
	return filepath.Join(s.cwd, path)
}

func (s *shell) setAlias(name, value string) {
	if _, exists := s.aliases[name]; !exists {
		s.aliasOrder = append(s.aliasOrder, name)
	}
	s.aliases[name] = value
}

func (s *shell) setEnv(name, value string) {
	s.env[name] = value
	switch name {
	case "PROMPT":
		s.prompt = value
	case "HOME":
		s.home = value
	}
}

func splitAssignments(words []wordNode) ([]assignment, []wordNode) {
	assignments := []assignment{}
	index := 0
	for index < len(words) {
		text, ok := literalWord(words[index])
		if !ok {
			break
		}
		name, value, ok := splitAssignment(text)
		if !ok {
			break
		}
		assignments = append(assignments, assignment{name: name, value: value})
		index++
	}
	return assignments, words[index:]
}

func splitAssignment(text string) (string, string, bool) {
	name, value, ok := strings.Cut(text, "=")
	if !ok || name == "" {
		return "", "", false
	}
	for i, r := range name {
		if i == 0 {
			if !(r == '_' || (r >= 'A' && r <= 'Z') || (r >= 'a' && r <= 'z')) {
				return "", "", false
			}
			continue
		}
		if !(r == '_' || (r >= 'A' && r <= 'Z') || (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9')) {
			return "", "", false
		}
	}
	return name, value, true
}

func assignmentWord(assign assignment) wordNode {
	return wordNode{
		parts: []wordPart{{kind: partLiteral, text: assign.name + "=" + assign.value}},
	}
}

func parseAliasWords(text string) ([]wordNode, bool) {
	node, err := parseScriptSafe(text)
	if err != nil || len(node.nodes) != 1 {
		return nil, false
	}
	andOr := node.nodes[0]
	if len(andOr.rest) != 0 || len(andOr.first.commands) != 1 {
		return nil, false
	}
	return andOr.first.commands[0].words, true
}

func lookupExecutable(name, pathEnv, cwd string) (string, error) {
	if strings.ContainsRune(name, '/') {
		path := name
		if !filepath.IsAbs(path) {
			path = filepath.Join(cwd, path)
		}
		if isExecutable(path) {
			return path, nil
		}
		return "", os.ErrNotExist
	}

	for _, dir := range filepath.SplitList(pathEnv) {
		if dir == "" {
			dir = "."
		}
		path := filepath.Join(dir, name)
		if !filepath.IsAbs(path) {
			path = filepath.Join(cwd, path)
		}
		if isExecutable(path) {
			return path, nil
		}
	}
	return "", os.ErrNotExist
}

func isExecutable(path string) bool {
	info, err := os.Stat(path)
	if err != nil || info.IsDir() {
		return false
	}
	return info.Mode()&0o111 != 0
}

func envList(env map[string]string) []string {
	keys := make([]string, 0, len(env))
	for key := range env {
		keys = append(keys, key)
	}
	sort.Strings(keys)
	values := make([]string, 0, len(keys))
	for _, key := range keys {
		values = append(values, key+"="+env[key])
	}
	return values
}

