}

func (s *shell) renderPrompt() string {
	return s.expandPromptString(s.prompt)
}

func (s *shell) expandPromptString(input string) string {
	var b strings.Builder
	for i := 0; i < len(input); {
		if input[i] != '\\' {
			b.WriteByte(input[i])
			i++
			continue
		}
		if strings.HasPrefix(input[i:], `\if{`) {
			cond, thenExpr, elseExpr, next, ok := parsePromptIf(input, i)
			if ok {
				if s.promptCondition(cond) {
					b.WriteString(s.expandPromptString(thenExpr))
				} else {
					b.WriteString(s.expandPromptString(elseExpr))
				}
				i = next
				continue
			}
		}
		if strings.HasPrefix(input[i:], `\{`) {
			end := strings.IndexByte(input[i+2:], '}')
			if end >= 0 {
				token := input[i+2 : i+2+end]
				b.WriteString(s.promptToken(token))
				i += end + 3
				continue
			}
		}
		if strings.HasPrefix(input[i:], `\n`) {
			b.WriteByte('\n')
			i += 2
			continue
		}
		if strings.HasPrefix(input[i:], `\$`) {
			b.WriteByte('$')
			i += 2
			continue
		}
		if i+1 < len(input) {
			b.WriteByte(input[i+1])
			i += 2
			continue
		}
		b.WriteByte(input[i])
		i++
	}
	return b.String()
}

func (s *shell) promptToken(token string) string {
	switch token {
	case "username":
		if user := s.env["USER"]; user != "" {
			return user
		}
		if current, err := user.Current(); err == nil && current.Username != "" {
			return current.Username
		}
		return "unknown"
	case "hostname":
		name, err := os.Hostname()
		if err != nil {
			return ""
		}
		return name
	case "current_dir":
		return s.promptCurrentDir()
	case "repo_status":
		status, ok := s.repoStatus()
		if !ok {
			return ""
		}
		return status
	case "reset":
		return "\x1b[0m"
	case "bold":
		return "\x1b[1m"
	case "underline":
		return "\x1b[4m"
	case "red":
		return "\x1b[31m"
	case "blue":
		return "\x1b[34m"
	case "green":
		return "\x1b[32m"
	case "yellow":
		return "\x1b[33m"
	case "cyan":
		return "\x1b[36m"
	case "magenta":
		return "\x1b[35m"
	default:
		return ""
	}
}

func (s *shell) promptCurrentDir() string {
	if s.home == "" {
		return s.cwd
	}
	cleanHome := filepath.Clean(s.home)
	cleanCwd := filepath.Clean(s.cwd)
	if cleanCwd == cleanHome {
		return "~"
	}
	prefix := cleanHome + string(os.PathSeparator)
	if strings.HasPrefix(cleanCwd, prefix) {
		return "~/" + strings.TrimPrefix(cleanCwd, prefix)
	}
	return cleanCwd
}

func (s *shell) promptCondition(cond string) bool {
	switch cond {
	case "in_remote":
		return s.env["SSH_CLIENT"] != ""
	case "in_repo":
		_, ok := s.repoStatus()
		return ok
	default:
		return false
	}
}

func (s *shell) repoStatus() (string, bool) {
	branchCmd := exec.Command("git", "rev-parse", "--abbrev-ref", "HEAD")
	branchCmd.Dir = s.cwd
	branchCmd.Env = envList(s.env)
	branchOut, err := branchCmd.Output()
	if err != nil {
		return "", false
	}
	branch := strings.TrimSpace(string(branchOut))
	if branch == "" {
		return "", false
	}

	statusCmd := exec.Command("git", "status", "--porcelain", "--ignore-submodules=dirty")
	statusCmd.Dir = s.cwd
	statusCmd.Env = envList(s.env)
	statusOut, err := statusCmd.Output()
	if err == nil && strings.TrimSpace(string(statusOut)) != "" {
		branch += "*"
	}
	return branch, true
}

func parsePromptIf(input string, start int) (cond, thenExpr, elseExpr string, next int, ok bool) {
	index := start + len(`\if{`)
	value, nextIndex, ok := parsePromptBrace(input, index)
	if !ok {
		return "", "", "", start, false
	}
	cond = value
	if nextIndex >= len(input) || input[nextIndex] != '{' {
		return "", "", "", start, false
	}
	thenExpr, nextIndex, ok = parsePromptBrace(input, nextIndex+1)
	if !ok || nextIndex >= len(input) || input[nextIndex] != '{' {
		return "", "", "", start, false
	}
	elseExpr, nextIndex, ok = parsePromptBrace(input, nextIndex+1)
	if !ok {
		return "", "", "", start, false
	}
	return cond, thenExpr, elseExpr, nextIndex, true
}

func parsePromptBrace(input string, start int) (string, int, bool) {
	depth := 1
	var b strings.Builder
	for i := start; i < len(input); i++ {
		switch input[i] {
		case '{':
			depth++
			b.WriteByte(input[i])
		case '}':
			depth--
			if depth == 0 {
				return b.String(), i + 1, true
			}
			b.WriteByte(input[i])
		default:
			b.WriteByte(input[i])
		}
	}
	return "", start, false
}

package main

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

const version = "0.4.2"

type options struct {
	command *string
	file    string
	login   bool
	norc    bool
}

func main() {
	name := filepath.Base(os.Args[0])
	opts, errText, errCode := parseOptions(name, os.Args[1:])
	if errText != "" {
		fmt.Fprint(os.Stderr, errText)
		os.Exit(errCode)
	}

	if opts == nil {
		return
	}

	sh, err := newShell(os.Stdin, os.Stdout, os.Stderr)
	if err != nil {
		fmt.Fprintf(os.Stderr, "nsh: %v\n", err)
		os.Exit(1)
	}
	sh.login = opts.login
	sh.ensureStateFiles()

	if !opts.norc {
		if status := sh.loadRCFiles(); status != 0 {
			os.Exit(status)
		}
	}

	switch {
	case opts.command != nil:
		os.Exit(sh.executeString(*opts.command))
	case opts.file != "":
		content, err := os.ReadFile(opts.file)
		if err != nil {
			printFilePanic(err)
			os.Exit(101)
		}
		os.Exit(sh.executeString(string(content)))
	default:
		if !isTTY(os.Stdout.Fd()) {
			fmt.Fprintln(os.Stderr, "nsh: warning: stdout is not a tty")
