}

func baseUsage(name string) string {
	return fmt.Sprintf("%s [FLAGS] [OPTIONS] [FILE]", name)
}

func commandUsage(name string, opts options) string {
	parts := []string{fmt.Sprintf("%s -c <command>", name)}
	if opts.login {
		parts = append(parts, "--login")
	}
	if opts.norc {
		parts = append(parts, "--norc")
	}
	return strings.Join(parts, " ")
}

func formatCLIError(message, usage string) string {
	return fmt.Sprintf("error: %s\n\nUSAGE:\n    %s\n\nFor more information try --help\n", message, usage)
}

