	fmt.Fprintf(os.Stderr, "failed to open the file: %s\n\n", formatRustOsError(err))
	fmt.Fprintln(os.Stderr, "nsh: Something went wrong. Check out ~/.nsh.log and please file this bug on GitHub: https://github.com/nuta/nsh/issues")
}

