import (
	"os"
	"strconv"
	"strings"
	"syscall"
	"unicode"
	"unicode/utf8"
	"unsafe"
)

func isTTY(fd uintptr) bool {
	var termios syscall.Termios
	_, _, errno := syscall.Syscall6(
		syscall.SYS_IOCTL,
		fd,
		uintptr(syscall.TCGETS),
		uintptr(unsafe.Pointer(&termios)),
		0,
		0,
		0,
	)
	return errno == 0
}

func formatRustOsError(err error) string {
	if pathErr, ok := err.(*os.PathError); ok {
		if errno, ok := pathErr.Err.(syscall.Errno); ok {
			return formatRustErrno(errno)
		}
	}
	if errno, ok := err.(syscall.Errno); ok {
		return formatRustErrno(errno)
	}
	return err.Error()
}

func formatRustErrno(errno syscall.Errno) string {
	kind := "Other"
	switch errno {
	case syscall.ENOENT:
		kind = "NotFound"
	case syscall.EACCES, syscall.EPERM:
		kind = "PermissionDenied"
	case syscall.EEXIST:
		kind = "AlreadyExists"
	}
	return "Os { code: " + strconv.Itoa(int(errno)) + ", kind: " + kind + ", message: " + quote(titleFirst(errno.Error())) + " }"
}

func quote(value string) string {
	return `"` + strings.ReplaceAll(value, `"`, `\"`) + `"`
}

func titleFirst(value string) string {
	if value == "" {
		return value
	}
	r, size := utf8.DecodeRuneInString(value)
	return string(unicode.ToUpper(r)) + value[size:]
}

package main

import (
	"bufio"
	"bytes"
	"fmt"
